1. import { Connection, PublicKey, TransactionInstruction } from '@solana/web3.js';
2. import {
3.   AccountInfo,
4.   ASSOCIATED_TOKEN_PROGRAM_ID,
5.   MintInfo,
6.   Token,
7.   TOKEN_PROGRAM_ID,
8. } from '@solana/spl-token';
9. import { AccountLayout } from '../layouts';
10. 
11. const FAILED_TO_FIND_ACCOUNT = 'Failed to find account';
12. const INVALID_ACCOUNT_OWNER = 'Invalid account owner';
13. 
14. export async function getTokenMint(
15.   connection: Connection,
16.   tokenMintPubkey: PublicKey,
17. ): Promise<MintInfo | undefined> {
18.   // @ts-ignore
19.   const token = new Token(connection, tokenMintPubkey, TOKEN_PROGRAM_ID, null);
20.   return token.getMintInfo();
21. }
22. 
23. /**
24.  * Retrieve the associated account or create one if not found.
25.  * This account may then be used as a `transfer()` or `approve()` destination
26.  */
27. export async function addAssociatedTokenAccount(
28.   connection: Connection,
29.   owner: PublicKey,
30.   mint: PublicKey,
31.   instructions: TransactionInstruction[],
32. ) {
33.   const associatedAddress = await Token.getAssociatedTokenAddress(
34.     ASSOCIATED_TOKEN_PROGRAM_ID,
35.     TOKEN_PROGRAM_ID,
36.     mint,
37.     owner,
38.   );
39. 
40.   let rentFee = 0;
41. 
42.   // This is the optimum logic, considering TX fee, client-side computation,
43.   // RPC roundtrips and guaranteed idempotent.
44.   // Sadly we can't do this atomically;
45.   try {
46.     const account = await connection.getAccountInfo(associatedAddress);
47.     if (!account) {
48.       // noinspection ExceptionCaughtLocallyJS
49.       throw new Error(FAILED_TO_FIND_ACCOUNT);
50.     }
51.   } catch (err: any) {
52.     // INVALID_ACCOUNT_OWNER can be possible if the associatedAddress has
53.     // already been received some lamports (= became system accounts).
54.     // Assuming program derived addressing is safe, this is the only case
55.     // for the INVALID_ACCOUNT_OWNER in this code-path
56.     if (err.message === FAILED_TO_FIND_ACCOUNT || err.message === INVALID_ACCOUNT_OWNER) {
57.       instructions.push(
58.         Token.createAssociatedTokenAccountInstruction(
59.           ASSOCIATED_TOKEN_PROGRAM_ID,
60.           TOKEN_PROGRAM_ID,
61.           mint,
