84.  * @param connection: An active web3js connection.
85.  * @param stakePoolAddress: The public key (address) of the stake pool account.
86.  */
87. export async function getStakePoolAccount(
88.   connection: Connection,
89.   stakePoolAddress: PublicKey,
90. ): Promise<StakePoolAccount> {
91.   const account = await connection.getAccountInfo(stakePoolAddress);
92. 
93.   if (!account) {
94.     throw new Error('Invalid stake pool account');
95.   }
96. 
97.   return {
98.     pubkey: stakePoolAddress,
99.     account: {
100.       data: StakePoolLayout.decode(account.data),
101.       executable: account.executable,
102.       lamports: account.lamports,
103.       owner: account.owner,
104.     },
105.   };
