108. /**
109.  * Retrieves and deserializes a Stake account using a web3js connection and the stake address.
110.  * @param connection: An active web3js connection.
111.  * @param stakeAccount: The public key (address) of the stake account.
112.  */
113. export async function getStakeAccount(
114.   connection: Connection,
115.   stakeAccount: PublicKey,
116. ): Promise<StakeAccount> {
117.   const result = (await connection.getParsedAccountInfo(stakeAccount)).value;
118.   if (!result || !('parsed' in result.data)) {
119.     throw new Error('Invalid stake account');
120.   }
121.   const program = result.data.program;
122.   if (program != 'stake') {
123.     throw new Error('Not a stake account');
124.   }
125.   const parsed = create(result.data.parsed, StakeAccount);
126. 
127.   return parsed;
128. }
