130. /**
131.  * Retrieves all StakePool and ValidatorList accounts that are running a particular StakePool program.
132.  * @param connection: An active web3js connection.
133.  * @param stakePoolProgramAddress: The public key (address) of the StakePool program.
134.  */
135. export async function getStakePoolAccounts(
136.   connection: Connection,
137.   stakePoolProgramAddress: PublicKey,
138. ): Promise<(StakePoolAccount | ValidatorListAccount)[] | undefined> {
139.   const response = await connection.getProgramAccounts(stakePoolProgramAddress);
140. 
141.   return response.map((a) => {
142.     let decodedData;
143. 
144.     if (a.account.data.readUInt8() === 1) {
145.       try {
146.         decodedData = StakePoolLayout.decode(a.account.data);
147.       } catch (error) {
148.         console.log('Could not decode StakeAccount. Error:', error);
149.         decodedData = undefined;
150.       }
151.     } else if (a.account.data.readUInt8() === 2) {
152.       try {
153.         decodedData = ValidatorListLayout.decode(a.account.data);
154.       } catch (error) {
155.         console.log('Could not decode ValidatorList. Error:', error);
156.         decodedData = undefined;
157.       }
158.     } else {
159.       console.error(
160.         `Could not decode. StakePoolAccount Enum is ${a.account.data.readUInt8()}, expected 1 or 2!`,
161.       );
162.       decodedData = undefined;
163.     }
164. 
165.     return {
166.       pubkey: a.pubkey,
167.       account: {
168.         data: decodedData,
169.         executable: a.account.executable,
170.         lamports: a.account.lamports,
171.         owner: a.account.owner,
172.       },
173.     };
174.   });
175. }
