177. /**
178.  * Creates instructions required to deposit stake to stake pool.
179.  */
180. export async function depositStake(
181.   connection: Connection,
182.   stakePoolAddress: PublicKey,
183.   authorizedPubkey: PublicKey,
184.   validatorVote: PublicKey,
185.   depositStake: PublicKey,
186.   poolTokenReceiverAccount?: PublicKey,
187. ) {
188.   const stakePool = await getStakePoolAccount(connection, stakePoolAddress);
189. 
190.   const withdrawAuthority = await findWithdrawAuthorityProgramAddress(
191.     STAKE_POOL_PROGRAM_ID,
192.     stakePoolAddress,
193.   );
194. 
195.   const validatorStake = await findStakeProgramAddress(
196.     STAKE_POOL_PROGRAM_ID,
197.     validatorVote,
198.     stakePoolAddress,
199.   );
200. 
201.   const instructions: TransactionInstruction[] = [];
202.   const signers: Signer[] = [];
203. 
204.   const poolMint = stakePool.account.data.poolMint;
205. 
206.   let rentFee = 0;
207. 
208.   // Create token account if not specified
209.   if (!poolTokenReceiverAccount) {
210.     const { associatedAddress, rentFee: fee } = await addAssociatedTokenAccount(
211.       connection,
212.       authorizedPubkey,
213.       poolMint,
214.       instructions,
215.     );
216.     poolTokenReceiverAccount = associatedAddress;
217.     rentFee += fee;
218.   }
219. 
220.   instructions.push(
221.     ...StakeProgram.authorize({
222.       stakePubkey: depositStake,
223.       authorizedPubkey,
224.       newAuthorizedPubkey: stakePool.account.data.stakeDepositAuthority,
225.       stakeAuthorizationType: StakeAuthorizationLayout.Staker,
226.     }).instructions,
227.   );
228. 
229.   instructions.push(
230.     ...StakeProgram.authorize({
231.       stakePubkey: depositStake,
232.       authorizedPubkey,
233.       newAuthorizedPubkey: stakePool.account.data.stakeDepositAuthority,
234.       stakeAuthorizationType: StakeAuthorizationLayout.Withdrawer,
235.     }).instructions,
236.   );
237. 
238.   instructions.push(
239.     StakePoolInstruction.depositStake({
240.       stakePool: stakePoolAddress,
241.       validatorList: stakePool.account.data.validatorList,
242.       depositAuthority: stakePool.account.data.stakeDepositAuthority,
243.       reserveStake: stakePool.account.data.reserveStake,
244.       managerFeeAccount: stakePool.account.data.managerFeeAccount,
245.       referralPoolAccount: poolTokenReceiverAccount,
246.       destinationPoolAccount: poolTokenReceiverAccount,
247.       withdrawAuthority,
248.       depositStake,
249.       validatorStake,
250.       poolMint,
251.     }),
252.   );
253. 
254.   return {
255.     instructions,
256.     signers,
257.     rentFee,
258.   };
259. }
