261. /**
262.  * Creates instructions required to deposit sol to stake pool.
263.  */
264. export async function depositSol(
265.   connection: Connection,
266.   stakePoolAddress: PublicKey,
267.   from: PublicKey,
268.   lamports: number,
269.   destinationTokenAccount?: PublicKey,
270.   referrerTokenAccount?: PublicKey,
271.   depositAuthority?: PublicKey,
272. ) {
273.   const fromBalance = await connection.getBalance(from, 'confirmed');
274.   if (fromBalance < lamports) {
275.     throw new Error(
276.       `Not enough SOL to deposit into pool. Maximum deposit amount is ${lamportsToSol(
277.         fromBalance,
278.       )} SOL.`,
279.     );
280.   }
281. 
282.   const stakePoolAccount = await getStakePoolAccount(connection, stakePoolAddress);
283.   const stakePool = stakePoolAccount.account.data;
284. 
285.   // Ephemeral SOL account just to do the transfer
286.   const userSolTransfer = new Keypair();
287.   const signers: Signer[] = [userSolTransfer];
288.   const instructions: TransactionInstruction[] = [];
289. 
290.   let rentFee = 0;
291. 
292.   // Create the ephemeral SOL account
293.   instructions.push(
294.     SystemProgram.transfer({
295.       fromPubkey: from,
296.       toPubkey: userSolTransfer.publicKey,
297.       lamports,
298.     }),
299.   );
300. 
301.   // Create token account if not specified
302.   if (!destinationTokenAccount) {
303.     const { associatedAddress, rentFee: fee } = await addAssociatedTokenAccount(
304.       connection,
305.       from,
306.       stakePool.poolMint,
307.       instructions,
308.     );
309.     destinationTokenAccount = associatedAddress;
310.     rentFee += fee;
311.   }
312. 
313.   const withdrawAuthority = await findWithdrawAuthorityProgramAddress(
314.     STAKE_POOL_PROGRAM_ID,
315.     stakePoolAddress,
316.   );
317. 
318.   instructions.push(
319.     StakePoolInstruction.depositSol({
320.       stakePool: stakePoolAddress,
321.       reserveStake: stakePool.reserveStake,
322.       fundingAccount: userSolTransfer.publicKey,
323.       destinationPoolAccount: destinationTokenAccount,
324.       managerFeeAccount: stakePool.managerFeeAccount,
325.       referralPoolAccount: referrerTokenAccount ?? destinationTokenAccount,
326.       poolMint: stakePool.poolMint,
327.       lamports,
328.       withdrawAuthority,
329.       depositAuthority,
330.     }),
331.   );
332. 
333.   return {
334.     instructions,
335.     signers,
336.     rentFee,
337.   };
338. }
