616.     throw new Error(
617.       `Not enough token balance to withdraw ${lamportsToSol(poolAmount)} pool tokens.
618.           Maximum withdraw amount is ${lamportsToSol(tokenAccount.amount.toNumber())} pool tokens.`,
619.     );
620.   }
621. 
622.   // Construct transaction to withdraw from withdrawAccounts account list
623.   const instructions: TransactionInstruction[] = [];
