676. /**
677.  * Creates instructions required to increase validator stake.
678.  */
679. export async function increaseValidatorStake(
680.   connection: Connection,
681.   stakePoolAddress: PublicKey,
682.   validatorVote: PublicKey,
683.   lamports: number,
684.   ephemeralStakeSeed?: number,
685. ) {
686.   const stakePool = await getStakePoolAccount(connection, stakePoolAddress);
687. 
688.   const validatorList = await getValidatorListAccount(
689.     connection,
690.     stakePool.account.data.validatorList,
691.   );
692. 
693.   const validatorInfo = validatorList.account.data.validators.find(
694.     (v) => v.voteAccountAddress.toBase58() == validatorVote.toBase58(),
695.   );
696. 
697.   if (!validatorInfo) {
698.     throw new Error('Vote account not found in validator list');
699.   }
700. 
701.   const withdrawAuthority = await findWithdrawAuthorityProgramAddress(
702.     STAKE_POOL_PROGRAM_ID,
703.     stakePoolAddress,
704.   );
705. 
706.   const transientStakeSeed = validatorInfo.transientSeedSuffixStart.addn(1); // bump up by one to avoid reuse
707. 
708.   const transientStake = await findTransientStakeProgramAddress(
709.     STAKE_POOL_PROGRAM_ID,
710.     validatorInfo.voteAccountAddress,
711.     stakePoolAddress,
712.     transientStakeSeed,
713.   );
714. 
715.   const validatorStake = await findStakeProgramAddress(
716.     STAKE_POOL_PROGRAM_ID,
717.     validatorInfo.voteAccountAddress,
718.     stakePoolAddress,
719.   );
720. 
721.   const instructions: TransactionInstruction[] = [];
722. 
723.   if (ephemeralStakeSeed != undefined) {
724.     const ephemeralStake = await findEphemeralStakeProgramAddress(
725.       STAKE_POOL_PROGRAM_ID,
726.       stakePoolAddress,
727.       new BN(ephemeralStakeSeed),
728.     );
729.     StakePoolInstruction.increaseAdditionalValidatorStake({
730.       stakePool: stakePoolAddress,
731.       staker: stakePool.account.data.staker,
732.       validatorList: stakePool.account.data.validatorList,
733.       reserveStake: stakePool.account.data.reserveStake,
734.       transientStakeSeed: transientStakeSeed.toNumber(),
735.       withdrawAuthority,
736.       transientStake,
737.       validatorStake,
738.       validatorVote,
739.       lamports,
740.       ephemeralStake,
741.       ephemeralStakeSeed,
742.     });
743.   } else {
744.     instructions.push(
745.       StakePoolInstruction.increaseValidatorStake({
746.         stakePool: stakePoolAddress,
